const BASE_URL = 'https://learninglab.doneverse.com/admin';
const LW_CLIENT = '68c4261f15eefcc20b0d6556';
const ITEMS_PER_PAGE = 200;

function normEmail(s) {
  return String(s || '')
    .replace(/\u00A0/g, ' ')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .trim()
    .toLowerCase();
}

function ensureEmailArray(x) {
  if (Array.isArray(x)) return x.map(normEmail).filter(Boolean);

  if (typeof x === 'string') {
    const s = x.trim();
    if (!s) return [];

    try {
      const parsed = JSON.parse(s);

      if (Array.isArray(parsed)) return parsed.map(normEmail).filter(Boolean);

      if (typeof parsed === 'string') {
        const inner = parsed.trim();
        if (inner.startsWith('[') && inner.endsWith(']')) {
          const parsed2 = JSON.parse(inner);
          if (Array.isArray(parsed2)) return parsed2.map(normEmail).filter(Boolean);
        }
      }
    } catch (e) {}

    return s.split(',').map(normEmail).filter(Boolean);
  }

  return [];
}

async function fetchUsersPage({ token, page }) {
  const url =
    `${BASE_URL}/api/v2/users` +
    `?page=${encodeURIComponent(page)}` +
    `&items_per_page=${encodeURIComponent(ITEMS_PER_PAGE)}`;

  return await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: {
      Accept: 'application/json',
      Authorization: `Bearer ${token}`,
      'Lw-Client': LW_CLIENT,
    },
    json: true,
  });
}

const edit = $('Edit Fields').first().json;
const token = edit.token;
if (!token) throw new Error('Missing token from node "Edit Fields" (expected .json.token)');

const wantedArr = ensureEmailArray(edit.emails);
const wanted = new Set(wantedArr);

if (wanted.size === 0) {
  return [{ json: { userIds: '', matchedUsers: [], missingEmails: [], wantedCount: 0, matchedCount: 0 } }];
}

const matchedByEmail = new Map(); // email -> id
const matchedIds = new Set();

// Optional. keep a tiny sample of LW emails for sanity checking
const sampleSeen = [];
const SAMPLE_LIMIT = 25;

let page = 1;
let totalPages = null;

while (true) {
  const res = await fetchUsersPage.call(this, { token, page });

  const users = Array.isArray(res?.data) ? res.data : null;
  if (users === null) {
    throw new Error(
      `Unexpected response shape. Expected { data: [...], meta: {...} }. ` +
      `Top-level keys: ${Object.keys(res || {}).join(',')}`
    );
  }

  for (const u of users) {
    const email = normEmail(u?.email);
    const id = u?.id != null ? String(u.id) : null;

    if (email && sampleSeen.length < SAMPLE_LIMIT) sampleSeen.push(email);

    if (email && id && wanted.has(email)) {
      if (!matchedByEmail.has(email)) matchedByEmail.set(email, id);
      matchedIds.add(id);
    }
  }

  if (totalPages === null) {
    totalPages = Number(res?.meta?.totalPages);
    if (!Number.isFinite(totalPages) || totalPages < 1) totalPages = 1;
  }

  // Stop early if we found everyone
  if (matchedByEmail.size >= wanted.size) break;

  page += 1;
  if (page > totalPages) break;
}

// Build missing list (emails we wanted but never saw)
const missingEmails = [];
for (const em of wanted) {
  if (!matchedByEmail.has(em)) missingEmails.push(em);
}

const matchedUsers = Array.from(matchedByEmail.entries()).map(([email, id]) => ({ email, id }));

return [
  {
    json: {
      userIds: Array.from(matchedIds).join(','),
      matchedUsers,
      missingEmails,
      wantedCount: wanted.size,
      matchedCount: matchedIds.size,
      pagesFetched: totalPages == null ? page : Math.min(page, totalPages),
      sampleSeenEmails: sampleSeen,
      vma: $input.first().json.vma
    },
  },
];

const out = [];

for (const item of items) {
  const root = item.json;

  // Your shape: an array with first element holding { data: [...] }
  const data = Array.isArray(root) ? root?.[0]?.data : root?.data;

  if (!Array.isArray(data)) {
    // Keep output valid for n8n, but empty if shape is unexpected
    out.push({ json: { userIds: '' } });
    continue;
  }

  const ids = data
    .map(u => u?.id)
    .filter(Boolean)
    .map(String);

  // Optional: de-dupe while preserving order
  const seen = new Set();
  const uniqueIds = [];
  for (const id of ids) {
    if (!seen.has(id)) {
      seen.add(id);
      uniqueIds.push(id);
    }
  }

  out.push({ json: { userIds: uniqueIds.join(',') } });
}

return out;

function extractRows(j) {
  // Handles common shapes depending on HTTP node / merge node output
  if (Array.isArray(j?.data)) return j.data;
  if (Array.isArray(j?.body?.data)) return j.body.data;
  if (Array.isArray(j?.response?.data)) return j.response.data;

  // If the HTTP node returned the whole thing as an array of { data: [...] }
  if (Array.isArray(j) && j.length && Array.isArray(j[0]?.data)) return j.flatMap(x => x?.data || []);

  return [];
}

function normEmail(s) {
  return String(s ?? "")
    .replace(/\u00A0/g, " ")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .trim()
    .toLowerCase();
}

function getDayFromMerged(j) {
  // This must exist because you said you’re using merge approach.
  // It should be attached from the Split/Set side, e.g. { day: "DAY 2" }
  return String(j?.day ?? j?.Day ?? "").trim();
}

// Fixed DAY list: DAY 2 .. DAY 12
const DAYS = Array.from({ length: 11 }, (_, i) => `DAY ${i + 2}`);

// userKey -> { user_id, email, dayGrades: {DAY X: {grades:[], avg:null}} }
const users = new Map();

function ensureUser(userKey, user_id, email) {
  if (!users.has(userKey)) {
    const dayGrades = {};
    for (const d of DAYS) dayGrades[d] = { grades: [], avg: null };

    users.set(userKey, {
      user_id: user_id || null,
      email: email || null,
      dayGrades,
    });
  } else {
    // Fill missing id/email if we later find it
    const u = users.get(userKey);
    if (!u.user_id && user_id) u.user_id = user_id;
    if (!u.email && email) u.email = email;
  }
  return users.get(userKey);
}

for (const item of $input.all()) {
  const j = item.json ?? {};
  const day = getDayFromMerged(j);
  if (!day) continue;              // merge must provide day
  if (!DAYS.includes(day)) continue; // only DAY 2..DAY 12

  const rows = extractRows(j);
  if (!rows.length) continue;

  for (const r of rows) {
    const user_id = String(r?.user_id ?? r?.userId ?? "").trim();
    const email = normEmail(r?.email);

    // If both are empty, skip
    if (!user_id && !email) continue;

    const grade = Number(r?.grade);
    if (!Number.isFinite(grade)) continue;

    // Prefer user_id grouping, fallback to email grouping
    const userKey = user_id ? `uid:${user_id}` : `email:${email}`;

    const u = ensureUser(userKey, user_id, email);

    u.dayGrades[day].grades.push(grade);
  }
}

// Compute averages for all users and all days (including empty days)
const out = [];
for (const u of users.values()) {
  for (const d of DAYS) {
    const grades = u.dayGrades[d].grades;
    if (!grades.length) {
      u.dayGrades[d].avg = null;
      continue;
    }
    const sum = grades.reduce((a, b) => a + b, 0);
    const avg = sum / grades.length;
    u.dayGrades[d].avg = Math.round(avg * 100) / 100;
  }

  out.push({
    json: {
      user_id: u.user_id,
      email: u.email,
      dayGrades: u.dayGrades,
    },
  });
}

return out;

